18	@@ -0,0 +1,149 @@
19	+#include "ad_sim.h"
20	+
21	+#include <stdlib.h>
22	+
23	+#define TRIES 4
24	+
25	+static AdRect offset(AdRect r, int dh, int dv) {
26	+  r.left += dh;
27	+  r.right += dh;
28	+  r.top += dv;
29	+  r.bottom += dv;
30	+  return r;
31	+}
32	+
33	+static int intersects(const AdRect *a, const AdRect *b) {
34	+  return a->left < b->right && b->left < a->right && a->top < b->bottom && b->top < a->bottom;
35	+}
36	+
37	+static long rnd_mod(const AdSim *sim, long k) { return labs(sim->rnd() % k); }
38	+
39	+static AdRect random_inside_rect(const AdSim *sim) {
40	+  int w = sim->bounds.right - sim->bounds.left;
41	+  int h = sim->bounds.bottom - sim->bounds.top;
42	+  AdRect r;
43	+  r.top = sim->bounds.top + (int)rnd_mod(sim, h - AD_RECT);
44	+  r.left = sim->bounds.left + (int)rnd_mod(sim, w - AD_RECT);
45	+  r.bottom = r.top + AD_RECT;
46	+  r.right = r.left + AD_RECT;
47	+  return r;
48	+}
49	+
50	+static AdRect random_edge_rect(const AdSim *sim) {
51	+  int w = sim->bounds.right - sim->bounds.left;
52	+  int h = sim->bounds.bottom - sim->bounds.top;
53	+  AdRect r;
54	+  if (sim->rnd() % 2 != 0) {
55	+    r.bottom = sim->bounds.top;
56	+    r.left = sim->bounds.left + (int)rnd_mod(sim, w);
57	+    r.top = r.bottom - AD_RECT;
58	+    r.right = r.left + AD_RECT;
59	+  } else {
60	+    r.left = sim->bounds.right;
61	+    r.top = sim->bounds.top + (int)rnd_mod(sim, h);
62	+    r.right = r.left + AD_RECT;
63	+    r.bottom = r.top + AD_RECT;
64	+  }
65	+  return r;
66	+}
67	+
68	+int ad_sim_collision(const AdSim *sim, int i, AdRect cand, int *dv, int *dh) {
69	+  for (int k = 0; k < sim->n; k++) {
70	+    const AdFlyer *o = &sim->f[k];
71	+    if (k == i || !o->live || !intersects(&o->r, &cand)) continue;
72	+    int dl = o->r.left - cand.left;
73	+    int dt = o->r.top - cand.top;
74	+    if (abs(dt) < abs(dl)) {
75	+      *dv = -1;
76	+      *dh = 0;
77	+    } else {
78	+      *dv = 0;
79	+      *dh = cand.top < o->r.top ? -1 : 1;
80	+    }
81	+    return 1;
82	+  }
83	+  return 0;
84	+}
85	+
86	+static void create_flyer(AdSim *sim, int i) {
87	+  AdRect r = {0, 0, 0, 0};
88	+  int placed = 0;
89	+  for (int t = 0; t < TRIES && !placed; t++) {
90	+    r = sim->running ? random_edge_rect(sim) : random_inside_rect(sim);
91	+    int dv, dh;
92	+    placed = !ad_sim_collision(sim, i, r, &dv, &dh);
93	+  }
94	+  if (!placed) return;
95	+  long roll = rnd_mod(sim, 100);
96	+  AdFlyer *f = &sim->f[i];
97	+  f->live = 1;
98	+  f->toast = roll >= 75;
99	+  f->speed = f->toast ? 1 : roll >= 50 ? 3 : roll >= 25 ? 2 : 1;
100	+  f->frame = 0;
101	+  f->flap_down = 0;
102	+  f->r = r;
103	+}
104	+
105	+void ad_sim_init(AdSim *sim, AdRect bounds, int n, long (*rnd)(void)) {
106	+  if (n > AD_MAX_FLYERS) n = AD_MAX_FLYERS;
107	+  if (n < 0) n = 0;
108	+  for (int i = 0; i < AD_MAX_FLYERS; i++) sim->f[i] = (AdFlyer){0};
109	+  sim->bounds = bounds;
110	+  sim->n = n;
111	+  sim->rnd = rnd;
112	+  sim->running = 0;
113	+  for (int i = 0; i < n; i++) create_flyer(sim, i);
114	+  sim->running = 1;
115	+}
116	+
117	+static void draw_flyer(AdFlyer *f, AdDrawFn draw, void *ctx) {
118	+  draw(ctx, &f->r, f->toast ? 4 : f->frame);
119	+  if (f->toast) return;
120	+  if (f->flap_down) {
121	+    if (f->frame == 0) {
122	+      f->frame = 1;
123	+      f->flap_down = 0;
124	+    } else {
125	+      f->frame--;
126	+    }
127	+  } else if (f->frame == 3) {
128	+    f->frame = 2;
129	+    f->flap_down = 1;
130	+  } else {
131	+    f->frame++;
132	+  }
133	+}
134	+
135	+void ad_sim_draw_all(AdSim *sim, AdDrawFn draw, void *ctx) {
136	+  for (int i = 0; i < sim->n; i++) {
137	+    if (sim->f[i].live) draw_flyer(&sim->f[i], draw, ctx);
138	+  }
139	+}
140	+
141	+void ad_sim_step(AdSim *sim, AdDrawFn draw, void *ctx) {
142	+  for (int i = 0; i < sim->n; i++) {
143	+    if (!sim->f[i].live) create_flyer(sim, i);
144	+    if (sim->f[i].live) sim->f[i].r = offset(sim->f[i].r, -2, 1);
145	+  }
146	+  for (int i = 0; i < sim->n; i++) {
147	+    AdFlyer *f = &sim->f[i];
148	+    if (!f->live) continue;
149	+    if (!intersects(&f->r, &sim->bounds)) {
150	+      f->live = 0;
151	+      continue;
152	+    }
153	+    int s = f->speed - 1;
154	+    if (s > 0) {
155	+      AdRect cand = offset(f->r, -2 * s, s);
156	+      int dv, dh;
157	+      if (ad_sim_collision(sim, i, cand, &dv, &dh)) {
158	+        cand = offset(f->r, dh, -2 * dv);
159	+        int dv2, dh2;
160	+        if (!ad_sim_collision(sim, i, cand, &dv2, &dh2)) f->r = cand;
161	+      } else {
162	+        f->r = cand;
163	+      }
164	+    }
165	+    draw_flyer(f, draw, ctx);
166	+  }
167	+}
